#include <intrin.h>
#include <cstdint>
#include <string>
#include <vector>

inline std::int32_t fname_decrypt_index(std::uint32_t enc)
{
    if (!enc) return 0;
    std::uint32_t s = _byteswap_ulong(enc - 1);
    if (s == 0x6903C7EBu) return static_cast<std::int32_t>(-1761855468);
    return static_cast<std::int32_t>(s - 0x6903C7EBu);
}

inline std::int32_t fname_decrypt_number(std::uint32_t enc)
{
    if (!enc) return -1;
    std::uint32_t m = enc - 1;
    if (m == 0xA5F795C0u) return 1063913561;
    return static_cast<std::int32_t>(_byteswap_ulong(m) + 0x3F6A085Au);
}

inline std::uint32_t fname_step(std::uint32_t s)
{
    std::uint32_t t = 8013u * s + 4695698u;
    return t ^ (8u * s) ^ (t >> 11);
}

inline void fname_stream_decrypt(char* buf, std::uint32_t count, std::uint32_t key)
{
    std::uint32_t state = key;
    std::uint8_t hash = static_cast<std::uint8_t>(static_cast<std::uint32_t>(-71) * key);
    for (std::uint32_t i = 0; i < count; ++i) {
        std::uint8_t c = static_cast<std::uint8_t>(buf[i]);
        buf[i] = static_cast<char>(static_cast<std::uint8_t>((hash ^ c) + state + 1));
        hash = c;
        state = fname_step(state);
    }
}

inline std::string fname_to_string(std::int32_t index)
{
    std::int32_t decoded = fname_decrypt_index(static_cast<std::uint32_t>(index));
    if (!decoded) return "";

    std::uintptr_t pool = driver->module_base + 0x1C889440;
    std::uintptr_t block = driver::km->read<std::uint64_t>(pool + 0x10 + (static_cast<std::uint32_t>(decoded) >> 16) * 8);
    if (!block) return "";

    std::uintptr_t entry = block + 2 * static_cast<std::uint16_t>(decoded);
    std::uint16_t header = driver::km->read<std::uint16_t>(entry);
    std::uint32_t field = (static_cast<std::uint32_t>(header) >> 1) & 0x3FF;

    if (field == 0x30C) {
        std::int32_t base_index = fname_decrypt_index(driver::km->read<std::uint32_t>(entry + 6));
        std::int32_t number = fname_decrypt_number(driver::km->read<std::uint32_t>(entry + 2));
        std::string base = fname_to_string(base_index);
        if (base.empty()) return "";
        return base + "_" + std::to_string(number);
    }

    std::uint32_t length = field ^ 0x30C;
    if (!length) return "";

    bool wide = (header & 1) != 0;
    std::uint32_t bytes = wide ? 2u * length : length;

    std::vector<char> buf(bytes);
    driver::km->read(entry + 2, buf.data(), bytes);

    std::uint32_t t = 8013u * length + 4695698u;
    std::uint32_t key = t ^ (8u * length) ^ (t >> 11);
    fname_stream_decrypt(buf.data(), bytes, key);

    if (wide) {
        const std::uint16_t* w = reinterpret_cast<const std::uint16_t*>(buf.data());
        std::string out;
        out.reserve(length);
        for (std::uint32_t i = 0; i < length; ++i) out.push_back(static_cast<char>(w[i]));
        return out;
    }
    return std::string(buf.data(), length);
}

inline std::string fname_from_object(std::uintptr_t object)
{
    if (!object) return "";
    return fname_to_string(driver::km->read<std::int32_t>(object + 0x20));
}

