#include <intrin.h>
#include <cstdint>

inline std::uint32_t get_objects_count()
{
    std::uint32_t r9d = driver::km->read<std::uint32_t>(driver->module_base + 0x1C966F28);
    r9d = _byteswap_ulong(r9d);
    r9d += 0x7FD025BCu;
    return r9d;
}

inline std::uintptr_t get_object_by_index(std::uint32_t index, std::uint32_t serial)
{
    if (serial == 0) return 0;
    if (static_cast<std::int32_t>(index) < 0) return 0;

    std::uint32_t r9d = get_objects_count();
    if (static_cast<std::int32_t>(index) >= static_cast<std::int32_t>(r9d)) return 0;

    std::uint64_t r9 = static_cast<std::uint16_t>(index);

    std::uint64_t r10 = driver::km->read<std::uint64_t>(driver->module_base + 0x1C966F20);
    r10 = _byteswap_uint64(r10);

    std::uint32_t chunk_index = index >> 16;
    r9 = (r9 * 3) << 3;
    r9 += driver::km->read<std::uint64_t>(r10 + static_cast<std::uint64_t>(chunk_index) * 8 + 0x3AE65B74);

    if (r9 == 0) return 0;
    if (driver::km->read<std::uint32_t>(r9 + 0xC) != serial) return 0;

    return static_cast<std::uintptr_t>(r9);
}

