inline uintptr_t DecryptUWorld(uintptr_t module_base)
{
    uint64_t encrypted = ZenixSys::Read<uint64_t>(module_base + 0x1C14D610);
    if (!encrypted) return 0;

    uint64_t v = encrypted ^ 0xC2A8FFULL;
    v = _rotl64(v, 16);
    v ^= 0xF5136F13ULL;

    uintptr_t world = static_cast<uintptr_t>(v * 0x4F207DBE8FB1498DULL);

    if (world < 0x10000 || (world & 0x7) != 0) return 0;

    return world;
}

